sealed class NativeImage : IDisposable
{
    readonly long _size;
    public NativeImage(long size)
    {
        _size = size;
        /* allocate the native buffer */
        GC.AddMemoryPressure(_size);
    }
    public void Dispose()
    {
        /* free the native buffer */
        GC.RemoveMemoryPressure(_size);
    }
}

